# BDA Experiment 5: Sequence from 20 to 60; calculate mean, maximum and sum
# HOW TO RUN ON UBUNTU:
# 1. Install R if needed: sudo apt update && sudo apt install -y r-base
# 2. Open a terminal in the folder containing this file.
# 3. Run: Rscript experiment5_sequence_stats.R
# INPUT: No keyboard input is required. The sequence is generated by seq(20, 60).
# EXPECTED OUTPUT: Mean = 40; Maximum = 60; Sum = 1640.

numbers <- seq(from = 20, to = 60, by = 1)

cat("Sequence from 20 to 60:\n")
print(numbers)

cat("Mean:", mean(numbers), "\n")
cat("Maximum:", max(numbers), "\n")
cat("Sum:", sum(numbers), "\n")
